import {
	AfterViewInit,
	ChangeDetectionStrategy,
	Component,
	ElementRef,
	Inject,
	Input,
	NgZone,
	OnDestroy,
	PLATFORM_ID,
	ViewChild,
} from '@angular/core';
import { CommonModule, DatePipe, isPlatformBrowser } from '@angular/common';

import { BlogPost } from '../../../../providers/blog/wordpress-post.model';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../../core/services/translation.service';

const TITLE_MAX_LENGTH = 60;
const DESCRIPTION_MAX_LENGTH = 220;
// Fraction of the remaining distance the pill closes each frame (0–1).
// Same feel as the hero video's "Play video" pill on the home page.
const CURSOR_FOLLOW_EASE = 0.25;

@Component({
	selector: 'app-blog-card',
	standalone: true,
	imports: [CommonModule, DatePipe, TranslateModule],
	templateUrl: './blog-card.component.html',
	styleUrl: './blog-card.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BlogCardComponent implements AfterViewInit, OnDestroy {
	@Input({ required: true }) post!: BlogPost;

	@ViewChild('imageWrapper') private imageWrapper?: ElementRef<HTMLElement>;
	@ViewChild('cursorWrapper') private cursorWrapper?: ElementRef<HTMLElement>;
	@ViewChild('cursorPill') private cursorPill?: ElementRef<HTMLElement>;

	get displayTitle(): string {
		const title = this.post.title;
		return title.length > TITLE_MAX_LENGTH
			? `${title.slice(0, TITLE_MAX_LENGTH).trimEnd()}...`
			: title;
	}
	get displayDescription(): string {
		const description = this.post.excerpt;
		return description.length > DESCRIPTION_MAX_LENGTH
			? `${description.slice(0, DESCRIPTION_MAX_LENGTH).trimEnd()}...`
			: description;
	}

	// Cursor-following "View Blog" pill over the image. Runs entirely outside
	// Angular: native listeners record the target position and a rAF loop eases
	// the pill toward it, writing the transform straight to the DOM. Going
	// through template bindings meant every mousemove queued a change-detection
	// pass before the pill could move, which is what made it feel laggy.
	private cursorTargetX = 0;
	private cursorTargetY = 0;
	private cursorCurrentX = 0;
	private cursorCurrentY = 0;
	private cursorRafId: number | null = null;
	private cursorEase = CURSOR_FOLLOW_EASE;
	private removeCursorListeners?: () => void;

	constructor(
		public translationService: TranslationService,
		private readonly ngZone: NgZone,
		@Inject(PLATFORM_ID) private readonly platformId: Object,
	) {}

	ngAfterViewInit(): void {
		if (!isPlatformBrowser(this.platformId)) return;

		const wrapper = this.imageWrapper?.nativeElement;
		if (!wrapper) return;

		if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
			this.cursorEase = 1; // track 1:1, no easing
		}

		this.ngZone.runOutsideAngular(() => {
			const onEnter = (event: MouseEvent) => {
				this.updateCursorTarget(event, wrapper);
				// Snap to the pointer so the pill appears where the cursor is
				// instead of sliding in from wherever it was last hidden.
				this.cursorCurrentX = this.cursorTargetX;
				this.cursorCurrentY = this.cursorTargetY;
				this.applyCursorTransform();
				this.cursorPill?.nativeElement.classList.add('active');
				this.startCursorLoop();
			};
			const onMove = (event: MouseEvent) => this.updateCursorTarget(event, wrapper);
			const onLeave = () => {
				this.cursorPill?.nativeElement.classList.remove('active');
				this.stopCursorLoop();
			};

			wrapper.addEventListener('mouseenter', onEnter, { passive: true });
			wrapper.addEventListener('mousemove', onMove, { passive: true });
			wrapper.addEventListener('mouseleave', onLeave, { passive: true });

			this.removeCursorListeners = () => {
				wrapper.removeEventListener('mouseenter', onEnter);
				wrapper.removeEventListener('mousemove', onMove);
				wrapper.removeEventListener('mouseleave', onLeave);
			};
		});
	}

	ngOnDestroy(): void {
		this.removeCursorListeners?.();
		this.stopCursorLoop();
	}

	private updateCursorTarget(event: MouseEvent, wrapper: HTMLElement): void {
		const rect = wrapper.getBoundingClientRect();
		this.cursorTargetX = event.clientX - rect.left;
		this.cursorTargetY = event.clientY - rect.top;
	}

	private applyCursorTransform(): void {
		const el = this.cursorWrapper?.nativeElement;
		if (el) {
			el.style.transform = `translate3d(${this.cursorCurrentX}px, ${this.cursorCurrentY}px, 0)`;
		}
	}

	private startCursorLoop(): void {
		if (this.cursorRafId !== null) return;

		const step = () => {
			this.cursorCurrentX += (this.cursorTargetX - this.cursorCurrentX) * this.cursorEase;
			this.cursorCurrentY += (this.cursorTargetY - this.cursorCurrentY) * this.cursorEase;
			this.applyCursorTransform();
			this.cursorRafId = requestAnimationFrame(step);
		};

		this.cursorRafId = requestAnimationFrame(step);
	}

	private stopCursorLoop(): void {
		if (this.cursorRafId !== null) {
			cancelAnimationFrame(this.cursorRafId);
			this.cursorRafId = null;
		}
	}
}
