import { ChangeDetectionStrategy, Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { toObservable } from '@angular/core/rxjs-interop';
import { TranslateModule } from '@ngx-translate/core';
import { Observable } from 'rxjs';
import { distinctUntilChanged, switchMap } from 'rxjs/operators';

import { environment } from '../../../../environments/environment';
import { BlogService } from '../../../providers/blog/blog.service';
import { BlogPost } from '../../../providers/blog/wordpress-post.model';
import { TranslationService } from '../../../core/services/translation.service';
import { BlogCardComponent } from './blog-card/blog-card.component';

@Component({
	selector: 'app-blog',
	standalone: true,
	imports: [CommonModule, TranslateModule, BlogCardComponent],
	templateUrl: './blog.component.html',
	styleUrl: './blog.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BlogComponent implements OnInit {
	@Input() limit = 3;
	@Input() showTitle = true;

	readonly blogUrl = environment.wordpressBlogUrl;

	posts$!: Observable<BlogPost[]>;

	private readonly lang$ = toObservable(this.translationService.currentLang);

	constructor(
		private readonly blogService: BlogService,
		public readonly translationService: TranslationService
	) { }

	ngOnInit(): void {
		this.posts$ = this.lang$.pipe(
			distinctUntilChanged(),
			switchMap((lang) => this.blogService.getLatestPosts(this.limit, lang))
		);
	}
}
